const item = $input.first().json;

const telegramMsg = ` Backup Diario Completado
${item.fecha_backup}

Estado del sistema:
 Productos: ${item.total_productos}
 Ventas totales: ${item.total_ventas}
 Clientes: ${item.total_clientes}
 Entradas: ${item.total_entradas}
 Salidas: ${item.total_salidas}
 Alertas pendientes: ${item.alertas_pendientes}
 Ventas del día: Q${item.ventas_hoy}

Sistema operando correctamente.`;

const tabla = `
<tr><td>Productos</td><td>${item.total_productos}</td></tr>
<tr><td>Ventas totales</td><td>${item.total_ventas}</td></tr>
<tr><td>Clientes</td><td>${item.total_clientes}</td></tr>
<tr><td>Entradas</td><td>${item.total_entradas}</td></tr>
<tr><td>Salidas</td><td>${item.total_salidas}</td></tr>
<tr><td>Alertas pendientes</td><td>${item.alertas_pendientes}</td></tr>
<tr><td>Ventas del día</td><td>Q${item.ventas_hoy}</td></tr>`;

return [{
  json: {
    tabla: tabla,
    telegram: telegramMsg,
    fecha: item.fecha_backup
  }
}];
